 52	    )
 53	  ) ||
 54	  name.contains("_private_key_") ||
 55	  name.has_prefix("private_key_") ||
 56	  name.has_suffix("_private_key") ||
 57	  name == "pairing_code" ||
 58	  name.contains("_pairing_code_") ||
 59	  name.has_prefix("pairing_code_") ||
 60	  name.has_suffix("_pairing_code")
 61	}
