 63	///|
 64	fn credential_word(c : Char) -> Bool {
 65	  (c >= 'a' && c <= 'z') ||
 66	  (c >= 'A' && c <= 'Z') ||
 67	  (c >= '0' && c <= '9') ||
 68	  c == '_' ||
 69	  c == '-'
 70	}
 71	
 72	///|
 73	fn credential_space(c : Char) -> Bool {
 74	  c == ' ' || c == '\t'
 75	}
 76	
 77	///|
 78	fn credential_end(c : Char) -> Bool {
 79	  credential_space(c) ||
 80	  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
 81	}
 82	
 83	///|
 84	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 85	  let buffer = @buffer.Buffer(size_hint=end - start)
 86	  for i in start..<end {
 87	    buffer.write_char_utf8(chars[i])
 88	  }
 89	  @utf8.decode_lossy(buffer.to_bytes())
 90	}
 91	
 92	///|
 93	fn credential_hex(c : Char) -> Int32? {
 94	  match c {
 95	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 96	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 97	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 98	    _ => None
 99	  }
100	}
101	
102	///|
103	fn credential_parameter(name : String) -> String {
104	  let chars = name.iter().to_array()
105	  let buffer = @buffer.Buffer(size_hint=name.length())
106	  let mut i = 0
107	  while i < chars.length() {
108	    if chars[i] == '%' &&
109	      i + 2 < chars.length() &&
110	      credential_hex(chars[i + 1]) is Some(hi) &&
111	      credential_hex(chars[i + 2]) is Some(lo) {
112	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
113	      i += 3
114	    } else {
115	      buffer.write_char_utf8(chars[i])
116	      i += 1
117	    }
118	  }
119	  @utf8.decode_lossy(buffer.to_bytes())
120	}
121	
122	///|
123	fn redact_credentials(text : String) -> String {
124	  let chars = text.iter().to_array()
125	  let buffer = @buffer.Buffer(size_hint=text.length())
126	  let mut i = 0
127	  let mut url = false
128	  while i < chars.length() {
129	    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
130	      url = false
131	    }
132	    if chars[i] == ':' &&
133	      i + 2 < chars.length() &&
134	      chars[i + 1] == '/' &&
135	      chars[i + 2] == '/' {
136	      url = true
137	      buffer.write_string_utf8("://")
138	      i += 3
139	      let mut end = i
140	      let mut user_end = None
141	      while end < chars.length() &&
142	            !credential_end(chars[end]) &&
143	            !['/', '?'].contains(chars[end]) {
144	        if chars[end] == '@' {
145	          user_end = Some(end)
146	        }
147	        end += 1
148	      }
149	      if user_end is Some(end) {
150	        buffer.write_string_utf8("[redacted]@")
151	        i = end + 1
152	      }
153	      continue
154	    }
155	    if url && ['?', '&'].contains(chars[i]) {
156	      let start = i
157	      i += 1
158	      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
159	        i += 1
160	      }
161	      let name = credential_parameter(character_text(chars, start + 1, i))
162	      if i < chars.length() && chars[i] == '=' {
163	        i += 1
164	        buffer.write_string_utf8(character_text(chars, start, i))
165	        if credential_field(name, for_diagnostics=true) ||
166	          ["key", "code"].contains(name.to_lower()) {
167	          if i + 10 <= chars.length() &&
168	            character_text(chars, i, i + 10) == "[redacted]" {
169	            i += 10
170	          }
171	          while i < chars.length() && !credential_end(chars[i]) {
172	            i += 1
173	          }
174	          buffer.write_string_utf8("[redacted]")
175	        }
176	      } else {
177	        buffer.write_string_utf8(character_text(chars, start, i))
178	      }
179	      continue
180	    }
181	    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
182	      let start = i
183	      let mut end = i
184	      while end < chars.length() && credential_word(chars[end]) {
185	        end += 1
186	      }
187	      let word = character_text(chars, start, end)
188	      let lower = word.to_lower()
189	      if [
190	          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
191	        ]
192	        .iter()
193	        .any(prefix => lower.has_prefix(prefix)) ||
194	        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
195	        while end < chars.length() && !credential_end(chars[end]) {
196	          end += 1
197	        }
198	        buffer.write_string_utf8("[redacted]")
199	        i = end
200	        continue
201	      }
202	      let mut separator = end
203	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
204	        separator += 1
205	      }
206	      while separator < chars.length() && credential_space(chars[separator]) {
207	        separator += 1
208	      }
209	      if ["bearer", "basic"].contains(lower) &&
210	        separator > end &&
211	        separator < chars.length() {
212	        let mut value_end = separator
213	        if separator + 10 <= chars.length() &&
214	          character_text(chars, separator, separator + 10) == "[redacted]" {
215	          value_end = separator + 10
216	        }
217	        while value_end < chars.length() && !credential_end(chars[value_end]) {
218	          value_end += 1
219	        }
220	        let value = character_text(chars, separator, value_end).to_lower()
221	        if value_end > separator &&
222	          !["authentication", "auth", "token"].contains(value) {
223	          buffer.write_string_utf8(character_text(chars, start, separator))
224	          buffer.write_string_utf8("[redacted]")
225	          i = value_end
226	          continue
227	        }
228	      }
229	      let mut previous = start
230	      while previous > 0 && credential_space(chars[previous - 1]) {
231	        previous -= 1
232	      }
233	      let field_start = previous == 0 ||
234	        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
235	      let option = word.has_prefix("--")
236	      let prose_credential = (
237	          ["credential", "credentials"].contains(lower) && !field_start
238	        ) ||
239	        lower == "ssh_inject_git_credentials"
240	      let assignment = separator < chars.length() &&
241	        (
242	          chars[separator] == '=' ||
243	          (chars[separator] == ':' && !prose_credential)
244	        )
245	      if credential_field(word, for_diagnostics=true) &&
246	        (assignment || (option && separator > end)) {
247	        let mut value = if assignment { separator + 1 } else { separator }
248	        while value < chars.length() && credential_space(chars[value]) {
249	          value += 1
250	        }
251	        buffer.write_string_utf8(character_text(chars, start, value))
252	        let quoted_key = start > 0 &&
253	          end < chars.length() &&
254	          ['"', '\''].contains(chars[start - 1]) &&
255	          chars[start - 1] == chars[end]
256	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
257	          buffer.write_string_utf8("[redacted]")
258	          i = chars.length()
259	        } else if value + 10 <= chars.length() &&
260	          character_text(chars, value, value + 10) == "[redacted]" {
261	          buffer.write_string_utf8("[redacted]")
262	          i = value + 10
263	          while i < chars.length() && !credential_end(chars[i]) {
264	            i += 1
265	          }
266	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
267	          let quote = chars[value]
268	          buffer.write_char_utf8(quote)
269	          value += 1
270	          while value < chars.length() && chars[value] != quote {
271	            if chars[value] == '\\' && value + 1 < chars.length() {
272	              value += 1
273	            }
274	            value += 1
275	          }
276	          buffer.write_string_utf8("[redacted]")
277	          i = value
278	        } else {
279	          let mut value_end = value
280	          while value_end < chars.length() && !credential_end(chars[value_end]) {
281	            value_end += 1
282	          }
283	          let scheme = character_text(chars, value, value_end).to_lower()
284	          if scheme == "bearer" || scheme == "basic" {
285	            while value_end < chars.length() &&
286	                  credential_space(chars[value_end]) {
287	              value_end += 1
288	            }
289	            buffer.write_string_utf8(character_text(chars, value, value_end))
290	            value = value_end
291	            while value_end < chars.length() &&
292	                  !credential_end(chars[value_end]) {
293	              value_end += 1
294	            }
295	          }
296	          if value + 10 <= chars.length() &&
297	            character_text(chars, value, value + 10) == "[redacted]" {
298	            value_end = value + 10
299	          }
300	          if value_end > value {
301	            buffer.write_string_utf8("[redacted]")
302	          }
303	          i = value_end
304	        }
305	        continue
306	      }
307	      buffer.write_string_utf8(word)
308	      i = end
309	      continue
310	    }
311	    buffer.write_char_utf8(chars[i])
312	    i += 1
313	  }
314	  @utf8.decode_lossy(buffer.to_bytes())
315	}
