317	///|
318	fn Progress::safe_message(self : Progress, text : String) -> String? {
319	  guard terminal_text(text) is Some(text) else { return None }
320	  let lower = text.to_lower()
321	  if lower.contains("-----begin ") && lower.contains("private key-----") {
322	    self.private_key = REDACTED ")
323	    return Some("[private key redacted]")
324	  }
325	  if self.private_key {
326	    if lower.contains("-----end ") && lower.contains("private key-----") {
327	      self.private_key = false
328	    }
329	    return None
330	  }
331	  let known = redact_known_values(text, self.secrets)
332	  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
333	  if safe.length() > 1024 {
334	    safe = safe[:1024].to_owned() + "… [truncated]"
335	    self.details_truncated = true
336	  }
337	  Some(safe)
338	}
