 505	///|
 506	fn diagnostic_current_run_count(text : String) -> Int32 {
 507	  let mut count = 0
 508	  for line in text.split("\n") {
 509	    let event = @json.parse(line.to_owned()) catch { _ => Json::null() }
 510	    if field(event, "runId") == Some(Json::string(recording_run_id)) {
 511	      count += 1
 512	    }
 513	  }
 514	  count
 515	}
