 517	///|
 518	async fn save_diagnostic(
 519	  stage : String,
 520	  status : String,
 521	  exit_code? : Int32,
 522	  error_type? : String,
 523	  phase? : String,
 524	  duration_ms? : Double,
 525	  attempt? : Int32,
 526	  retry_delay_ms? : Int32,
 527	  timeout_ms? : Int32,
 528	  os_errno? : Int32,
 529	  source? : CreateEvidence,
 530	  error_message? : String,
 531	  details_truncated~ : Bool = false,
 532	  tunnel_directory? : String,
 533	  expected_workspace_uid? : String,
 534	  observed_workspace_uid? : String,
 535	  evidence? : Json,
 536	  evidence_incomplete~ : Bool = false,
 537	  evidence_stable_activity~ : Bool = false,
 538	  evidence_stable_operation~ : Bool = false,
 539	  run_completeness? : String,
 540	  recording? : Bool,
 541	  environment? : Map[String, String],
 542	  protected_secrets? : Array[String],
 543	) -> Unit {
 544	  if !recording.unwrap_or(
 545	      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
 546	    ) {
 547	    return
 548	  }
 549	  diagnostic_run_has_events.val = true
 550	  let event_time = @env.now()
 551	  let event : Json = {
 552	    "stage": stage,
 553	    "status": status,
 554	    "time": event_time.to_string(),
 555	    "runId": recording_run_id,
 556	    "adapterVersion": version,
 557	  }
 558	  if create_recording.attempt > 0 {
 559	    set_field(
 560	      event,
 561	      "createAttempt",
 562	      Json::number(create_recording.attempt.to_double()),
 563	    )
 564	    set_field(event, "createPhase", Json::string(create_recording.phase))
 565	  }
 566	  let process_environment = @env.get_env_vars()
 567	  let secrets = [] + protected_secrets.unwrap_or([])
 568	  if environment is Some(environment) {
 569	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
 570	      secrets.push(secret)
 571	    }
 572	  }
 573	  if tunnel_directory is Some(directory) &&
 574	    diagnostic_workspace_environments.get(directory) is Some(environment) {
 575	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
 576	      secrets.push(secret)
 577	    }
 578	  }
 579	  if error_message is Some(message) {
 580	    let message = diagnostic_text(
 581	      message,
 582	      environment=process_environment,
 583	      protected_secrets=secrets,
 584	    )
 585	    set_field(event, "errorMessage", Json::string(message))
 586	    set_field(
 587	      event,
 588	      "detailsTruncated",
 589	      Json::boolean(
 590	        details_truncated ||
 591	        message == "[error details incomplete or truncated]" ||
 592	        message.has_suffix("\n[error details incomplete or truncated]"),
 593	      ),
 594	    )
 595	  }
 596	  if tunnel_directory is Some(directory) {
 597	    set_field(
 598	      event,
 599	      "tunnelDirectory",
 600	      Json::string(
 601	        diagnostic_text(
 602	          directory,
 603	          environment=process_environment,
 604	          protected_secrets=secrets,
 605	        ),
 606	      ),
 607	    )
 608	  }
 609	  for
 610	    pair in [
 611	      ("expectedWorkspaceUid", expected_workspace_uid),
 612	      ("observedWorkspaceUid", observed_workspace_uid),
 613	    ] {
 614	    if pair.1 is Some(value) {
 615	      set_field(
 616	        event,
 617	        pair.0,
 618	        Json::string(
 619	          diagnostic_text(
 620	            value,
 621	            environment=process_environment,
 622	            protected_secrets=secrets,
 623	          ),
 624	        ),
 625	      )
 626	    }
 627	  }
 628	  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
 629	  if source is Some(evidence) {
 630	    let value = evidence.to_json()
 631	    if value.stringify().length() <= 65536 {
 632	      set_field(
 633	        event,
 634	        "source",
 635	        diagnostic_json(
 636	          value,
 637	          process_environment,
 638	          secrets,
 639	          evidence_truncated,
 640	          0,
 641	          stable_activity=evidence_stable_activity,
 642	        ),
 643	      )
 644	    } else {
 645	      evidence_truncated.val = true
 646	    }
 647	  }
 648	  if evidence is Some(value) {
 649	    if value.stringify().length() <= 65536 {
 650	      set_field(
 651	        event,
 652	        "evidence",
 653	        diagnostic_json(
 654	          value,
 655	          process_environment,
 656	          secrets,
 657	          evidence_truncated,
 658	          0,
 659	          stable_activity=evidence_stable_activity,
 660	          secret_states=stage == "server-environment",
 661	          stable_operation=evidence_stable_operation,
 662	        ),
 663	      )
 664	    } else {
 665	      evidence_truncated.val = true
 666	    }
 667	  }
 668	  if evidence_truncated.val {
 669	    set_field(event, "evidenceTruncated", Json::boolean(true))
 670	    set_field(event, "completeness", Json::string("partial"))
 671	  }
 672	  if details_truncated ||
 673	    evidence_truncated.val ||
 674	    (
 675	      error_message is Some(message) &&
 676	      message.contains("[error details incomplete or truncated]")
 677	    ) {
 678	    diagnostic_recording_health.run_partial = true
 679	  }
 680	  if run_completeness is Some(value) {
 681	    set_field(event, "runCompleteness", Json::string(value))
 682	  }
 683	  if os_errno is Some(code) && code > 0 && code < 4096 {
 684	    set_field(event, "osErrno", Json::number(code.to_double()))
 685	  }
 686	  if exit_code is Some(code) {
 687	    set_field(event, "exitCode", Json::number(code.to_double()))
 688	  }
 689	  for pair in [("errorType", error_type), ("phase", phase)] {
 690	    if pair.1 is Some(text) {
 691	      set_field(event, pair.0, Json::string(text))
 692	    }
 693	  }
 694	  if duration_ms is Some(value) {
 695	    set_field(event, "durationMs", Json::number(value))
 696	  }
 697	  if attempt is Some(value) {
 698	    set_field(event, "attempt", Json::number(value.to_double()))
 699	  }
 700	  if timeout_ms is Some(value) {
 701	    set_field(event, "timeoutMs", Json::number(value.to_double()))
 702	  }
 703	  if retry_delay_ms is Some(value) {
 704	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
 705	  }
 706	  let failed = error_type is Some(_) ||
 707	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
 708	      status,
 709	    )
 710	  if diagnostic_pending.length() >= 64 {
