 749	  defer {
 750	    diagnostic_write_active.val = false
 751	  }
 752	  let mut failure_phase = "directory"
 753	  let mut health_changed = false
 754	  @async.with_timeout(50, async fn() {
 755	    let dir = adapter_state_home()
 756	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
