 762	      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
 763	      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
 764	      return
 765	    }
 766	    let lock = @fs.open(
 767	      lock_path,
 768	      mode=ReadWrite,
 769	      create_mode=OpenOrCreate,
 770	      permission=0o600,
 771	    )
 772	    defer lock.close()
 773	    if !lock.try_lock(Exclusive) {
 774	      diagnostic_recording_warning("lock_busy", phase=failure_phase)
 775	      return
 776	    }
 777	    failure_phase = "inspect"
 778	    if @fs.exists(path) &&
 779	      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
