 796	      let size = file.size()
 797	      if size > 262144L {
 798	        let marker = diagnostic_recording_event("rotated", "retention_limit")
 799	        set_field(
 800	          marker,
 801	          "missingThroughTime",
 802	          Json::string(@env.now().to_string()),
 803	        )
 804	        set_field(marker, "missingRange", Json::string("unknown"))
