 827	            if read != size.to_int() {
 828	              "short_read"
 829	            } else {
 830	              "incomplete_record"
 831	            },
 832	          )
 833	          set_field(marker, "missingRange", Json::string("unknown"))
 834	          prefix += marker.stringify() + "\n"
 835	          prefix_markers += 1
 836	          retained = Some(
 837	            @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:complete]),
 838	          )
 839	          replace = true
 840	        }
 841	      }
 842	      if terminal && retained is None {
 843	        let bytes = FixedArray::make(size.to_int(), b'\x00')
