 863	      }
 864	    }
 865	    let recorded_drops = diagnostic_recording_health.dropped
 866	    let incident_serial = diagnostic_recording_health.incident_serial
 867	    if recorded_drops > 0 || diagnostic_recording_health.incident {
 868	      let marker = diagnostic_recording_event(
 869	        if recorded_drops > 0 {
 870	          "degraded"
 871	        } else {
 872	          "recovered"
 873	        },
 874	        diagnostic_recording_health.reason,
 875	      )
 876	      if recorded_drops > 0 {
 877	        set_field(
 878	          marker,
 879	          "droppedEvents",
 880	          Json::number(recorded_drops.to_double()),
 881	        )
 882	        set_field(
 883	          marker,
 884	          "missingFromTime",
 885	          Json::string(diagnostic_recording_health.first_dropped.to_string()),
 886	        )
 887	        set_field(
 888	          marker,
 889	          "missingThroughTime",
 890	          Json::string(diagnostic_recording_health.last_dropped.to_string()),
 891	        )
 892	      } else {
 893	        set_field(marker, "completeness", Json::string("complete"))
 894	      }
 895	      if diagnostic_recording_health.phase != "" {
 896	        set_field(
 897	          marker,
 898	          "phase",
 899	          Json::string(diagnostic_recording_health.phase),
 900	        )
 901	      }
 902	      if diagnostic_recording_health.os_errno is Some(code) {
