 905	      prefix += marker.stringify() + "\n"
 906	      prefix_markers += 1
 907	    }
 908	    let count = diagnostic_pending.length()
 909	    diagnostic_pending_inflight.val = count
 910	    defer {
 911	      diagnostic_pending_inflight.val = 0
 912	    }
 913	    let records = @buffer.Buffer(size_hint=4096)
 914	    for index in 0..<count {
