 928	        path,
 929	        content,
 930	        permission=0o600,
 931	        append=true,
 932	        create_mode=OpenOrCreate,
 933	      )
 934	    }
 935	    diagnostic_run_written_count.val += prefix_markers
 936	    for index in 0..<count {
