1174	///|
1175	fn diagnostic_protected_values(
1176	  value : Json,
1177	  result : DiagnosticProtectedValues,
1178	  output : String,
1179	  uncertain : Bool,
1180	  secret~ : Bool = false,
1181	  depth~ : Int32 = 0,
1182	) -> Unit {
1183	  if result.visited >= 65536 || depth >= 64 {
1184	    result.incomplete = true
1185	    return
1186	  }
1187	  result.visited += 1
1188	  match value {
1189	    Json::String(text) if text != "" && secret => {
1190	      let destination = result.secrets
1191	      diagnostic_add_protected(text, output, uncertain, destination, result)
1192	      for line in text.split("\n") {
1193	        if line != "" && line.length() < text.length() {
1194	          diagnostic_add_protected(
1195	            line.to_owned(),
1196	            output,
1197	            uncertain,
1198	            destination,
1199	            result,
1200	          )
1201	        }
1202	        for word in line.split(" ") {
1203	          for part in word.split("=") {
1204	            if part != "" && part.length() < text.length() {
1205	              diagnostic_add_protected(
1206	                part.to_owned(),
1207	                output,
1208	                uncertain,
1209	                destination,
1210	                result,
1211	              )
1212	            }
1213	          }
1214	        }
1215	      }
1216	      let escaped = Json::string(text).stringify()
1217	      if escaped.length() > 2 {
1218	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1219	        if encoded != text {
1220	          diagnostic_add_protected(
1221	            encoded, output, uncertain, destination, result,
1222	          )
1223	        }
1224	      }
1225	    }
1226	    Json::String(text) if text != "" => {
1227	      let mut next_secret = false
1228	      for word in text.split(" ") {
1229	        let word = word.to_owned()
1230	        if next_secret {
1231	          diagnostic_add_protected(
1232	            word,
1233	            output,
1234	            uncertain,
1235	            result.secrets,
1236	            result,
1237	          )
1238	          next_secret = false
1239	        } else if word.split_once("=") is Some((name, value)) {
1240	          if credential_field(name.to_owned(), for_diagnostics=true) {
1241	            diagnostic_add_protected(
1242	              value.to_owned(),
1243	              output,
1244	              uncertain,
1245	              result.secrets,
1246	              result,
1247	            )
1248	          }
1249	        } else if word.has_prefix("-") &&
1250	          credential_field(word, for_diagnostics=true) {
1251	          next_secret = true
1252	        }
1253	      }
1254	    }
1255	    Json::Array(values) =>
1256	      for item in values {
1257	        diagnostic_protected_values(
1258	          item,
1259	          result,
1260	          output,
1261	          uncertain,
1262	          secret~,
1263	          depth=depth + 1,
1264	        )
1265	      }
1266	    Json::Object(values) =>
1267	      for name, item in values {
1268	        let key = name.to_lower().replace_all(old="_", new="")
1269	        diagnostic_protected_values(
1270	          item,
1271	          result,
1272	          output,
1273	          uncertain,
1274	          secret=secret ||
1275	            credential_field(name, for_diagnostics=true) ||
1276	            key == "pairingcode",
1277	          depth=depth + 1,
1278	        )
1279	      }
1280	    _ => ()
1281	  }
1282	}
