1284	///|
1285	fn diagnostic_output(
1286	  output : Bytes,
1287	  environment : Map[String, String],
1288	  protected_input? : String,
1289	  protected_secrets? : Array[String],
1290	  omitted~ : Bool = false,
1291	) -> String? {
1292	  if output.length() == 0 {
1293	    return if omitted {
1294	      Some("[error details incomplete or truncated]")
1295	    } else {
1296	      None
1297	    }
1298	  }
1299	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1300	  let incomplete = omitted || limit < output.length()
1301	  let text = @utf8.decode_lossy(output[:limit])
1302	  let safeguards : DiagnosticProtectedValues = {
1303	    secrets: [],
1304	    visited: 0,
1305	    incomplete: false,
1306	  }
1307	  if protected_input is Some(input) {
1308	    diagnostic_protected_values(
1309	      @json.parse(input),
1310	      safeguards,
1311	      text,
1312	      incomplete,
1313	    ) catch {
1314	      _ => safeguards.incomplete = true
1315	    }
1316	  }
1317	  if safeguards.incomplete {
1318	    return Some(
1319	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1320	    )
1321	  }
1322	  Some(
1323	    diagnostic_text(
1324	      text,
1325	      environment~,
1326	      omitted=incomplete,
1327	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1328	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1329	    ),
1330	  )
1331	}
