1064	  let source_lines = message.split("\n").to_array()
1065	  for index in 0..<source_lines.length() {
1066	    let line = source_lines[index]
1067	    if lines.length() == 32 {
1068	      incomplete = true
1069	      ignore(lines.remove(1))
1070	    }
1071	    let truncated = line.length() > 1024
1072	    let bounded = if truncated {
1073	      incomplete = true
1074	      line[:1024].to_owned()
1075	    } else {
1076	      line.to_owned()
1077	    }
1078	    let bounded = if truncated ||
1079	      (incomplete_final_line && index == source_lines.length() - 1) {
1080	      diagnostic_partial_secret(bounded, progress.secrets)
1081	    } else {
1082	      bounded
1083	    }
1084	    match progress.safe_message(bounded) {
1085	      Some(safe) => lines.push(safe)
1086	      None => {
1087	        incomplete = true
1088	        lines.push("[unavailable]")
1089	      }
1090	    }
1091	  }
1092	  if (incomplete || progress.details_truncated) &&
1093	    lines.last() != Some("[error details incomplete or truncated]") {
1094	    lines.push("[error details incomplete or truncated]")
1095	  }
1096	  lines.join("\n")
1097	}
