1099	///|
1100	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1101	  let chars = text.iter().to_array()
1102	  let mut boundary = chars.length()
1103	  for secret in secrets {
1104	    let value = secret.iter().to_array()
1105	    if value.length() == 0 || text.has_suffix(secret) {
1106	      continue
1107	    }
1108	    let limit = if value.length() - 1 < boundary {
1109	      value.length() - 1
1110	    } else {
1111	      boundary
1112	    }
1113	    if limit == 0 {
1114	      continue
1115	    }
1116	    let prefixes = FixedArray::make(limit, 0)
1117	    let mut matched = 0
1118	    for index in 1..<limit {
1119	      while matched > 0 && value[matched] != value[index] {
1120	        matched = prefixes[matched - 1]
1121	      }
1122	      if value[matched] == value[index] {
1123	        matched += 1
1124	      }
1125	      prefixes[index] = matched
1126	    }
1127	    matched = 0
1128	    for index in 0..<boundary {
1129	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1130	        matched = prefixes[matched - 1]
1131	      }
1132	      if matched < limit && value[matched] == chars[index] {
1133	        matched += 1
1134	      }
1135	    }
1136	    boundary -= matched
1137	  }
1138	  if boundary == chars.length() {
1139	    text
1140	  } else {
1141	    character_text(chars, 0, boundary) + "[redacted]"
1142	  }
1143	}
