1146	priv struct DiagnosticProtectedValues {
1147	  secrets : Array[String]
1148	  mut visited : Int32
1149	  mut incomplete : Bool
1150	}
1151	
1152	///|
1153	fn diagnostic_add_protected(
1154	  value : String,
1155	  output : String,
1156	  uncertain : Bool,
1157	  destination : Array[String],
1158	  result : DiagnosticProtectedValues,
1159	) -> Unit {
1160	  if value == "" ||
1161	    (
1162	      !output.contains(value) &&
1163	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1164	    ) {
1165	    return
1166	  }
1167	  if result.secrets.length() >= 512 {
1168	    result.incomplete = true
1169	    return
1170	  }
1171	  destination.push(value)
1172	}
