122	fn sensitive_name(name : String) -> Bool {
123	  let credential = credential_field(name, for_diagnostics=true)
124	  let name = name.to_lower()
125	  credential ||
126	  [
127	    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
128	    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
129	  ]
130	  .iter()
131	  .any(marker => name.contains(marker))
132	}
