157	///|
158	fn Progress::new(
159	  stage : String,
160	  environment? : Map[String, String],
161	  recording_override? : Bool,
162	  context? : Json,
163	  protected_secrets? : Array[String],
164	  protection_incomplete~ : Bool = false,
165	) -> Progress {
166	  let secrets = []
167	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
168	    if sensitive_name(name) && value != "" {
169	      // Multiline credentials must also be masked in line-oriented output.
170	      add_protected_secret(secrets, value)
171	    }
172	  }
173	  if protected_secrets is Some(values) {
174	    for value in values {
175	      add_protected_secret(secrets, value)
176	    }
177	  }
178	  secrets.sort_by((a, b) => b.length().compare(a.length()))
179	  {
180	    stage,
181	    operations: {},
182	    builds: {},
183	    secrets,
184	    protection_incomplete,
185	    recording: recording_override.unwrap_or(
186	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
187	      Some("0"),
188	    ),
189	    context,
190	    phase_count: 0,
191	    private_key: false,
192	    classic_build: false,
193	    recent: [],
194	    failures: [],
195	    details_truncated: false,
196	  }
197	}
