267	///|
268	async fn Progress::status(self : Progress, event : Json) -> Unit {
269	  guard field(event, "phase") is Some(Json::String(phase)) &&
270	    phase_label(phase) is Some(label) &&
271	    field(event, "state") is Some(Json::String(state)) &&
272	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
273	    return
274	  }
275	  if self.phase_count < 128 {
276	    self.phase_count += 1
277	    save_diagnostic(
278	      self.stage,
279	      state,
280	      phase~,
281	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
282	      evidence?=self.context,
283	      evidence_stable_operation=true,
284	      protected_secrets=self.secrets,
285	      recording=self.recording,
286	    )
287	  } else if self.phase_count == 128 {
288	    self.phase_count += 1
289	    self.details_truncated = true
290	    save_diagnostic(
291	      self.stage,
292	      "diagnostics-truncated",
293	      error_type="phase_limit",
294	      phase~,
295	      evidence?=self.context,
296	      evidence_incomplete=true,
297	      evidence_stable_operation=true,
298	      protected_secrets=self.secrets,
299	      recording=self.recording,
300	    )
301	  }
302	  let key = ["pipeline", "operationId", "phase", "step"]
303	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
304	    .join(":")
305	  if state == "started" {
306	    if self.operations.length() >= 256 {
307	      self.operations.clear()
308	    }
309	    self.operations.set(key, @env.now())
310	    progress_message(label + ": running…")
311	  } else {
312	    let duration = match field(event, "durationMs") {
313	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
314	        Some(seconds(value.to_uint64()))
315	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
316	    }
317	    self.operations.remove(key)
318	    let timing = duration.map(value => value + ", ").unwrap_or("") +
319	      "elapsed " +
320	      seconds(@env.now() - progress_started)
321	    progress_message(
322	      label +
323	      ": " +
324	      (if state == "succeeded" { "done" } else { state }) +
325	      " (" +
326	      timing +
327	      ")",
328	    )
329	  }
330	}
