332	///|
333	fn classic_build_step(text : String) -> Bool {
334	  guard text.has_prefix("Step ") &&
335	    text[5:].split_once("/") is Some((step, rest)) &&
336	    rest.split_once(" ") is Some((total, detail)) else {
337	    return false
338	  }
339	  step.length() > 0 &&
340	  total.length() > 0 &&
341	  step.iter().all(c => c >= '0' && c <= '9') &&
342	  total.iter().all(c => c >= '0' && c <= '9') &&
343	  detail.trim().has_prefix(":")
344	}
