+) -> Array[String]? {
+  if !for_output && !state_recording(state) {
+    return Some([])
+  }
+  try {
+    let directory = required(state, "tunnelDirectory")
+    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
+      is Some(raw) else {
+      return None
+    }
+    let saved = @json.parse(raw)
+    guard saved is Json::Object(values) else { return None }
+    let environment : Map[String, String] = Map([])
+    for name, value in values {
+      guard value is Json::String(value) else { return None }
+      environment.set(name, value)
+    }
+    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
+    if include_pairing {
+      guard workspace_pairing_secrets(state) is Some(pairing) else {
+        return None
+      }
+      for value in pairing {
+        secrets.push(value)
+      }
+    }
+    Some(secrets)
+  } catch {
+    error => if @async.is_being_cancelled() { raise error } else { None }
+  }
+}
