+///|
+fn shell_wait_with_signals(command : String) -> String {
+  "child=; pending=; " +
+  "forward() { pending=$1; if test -n \"$child\"; then kill -s \"$pending\" \"$child\" 2>/dev/null || :; fi; }; " +
+  "trap 'forward TERM' TERM; trap 'forward INT' INT; trap 'forward HUP' HUP; " +
+  command +
+  " & child=$!; if test -n \"$pending\"; then kill -s \"$pending\" \"$child\" 2>/dev/null || :; fi; " +
+  "wait \"$child\"; result=$?; if test -n \"$pending\"; then wait \"$child\" 2>/dev/null || :; fi; " +
+  "case \"$pending\" in TERM) exit 143 ;; INT) exit 130 ;; HUP) exit 129 ;; esac; exit \"$result\""
+}
