+      RelayReadiness::Retry("transport_error")
+    }
   }
   match result {
-    Ready => ()
+    Ready =>
+      if record_success {
+        save_diagnostic(
+          "relay-probe",
+          "success",
+          phase~,
+          duration_ms=(@env.now() - started).to_double(),
+          evidence~,
+          tunnel_directory=directory,
+          environment~,
+          protected_secrets=pairing_secrets,
+          recording=state_recording(state),
+        )
+      }
