       save_diagnostic(
         "relay-probe",
         "pending",
         error_type="git_helper_unavailable",
+        phase~,
+        exit_code?,
+        error_message?=error_detail,
+        evidence~,
         duration_ms=(@env.now() - started).to_double(),
         tunnel_directory=directory,
-        recording=workspace_recording(state),
+        environment~,
+        protected_secrets=pairing_secrets,
+        recording=state_recording(state),
       )
     Retry(reason) =>
       save_diagnostic(
         "relay-probe",
-        "failed",
-        error_type=reason,
+        if cancelled {
+          "cancelled"
+        } else {
+          "failed"
+        },
+        error_type=if cancelled { "cancelled" } else { reason },
+        phase~,
+        exit_code?,
+        error_message?=error_detail,
+        timeout_ms?=if reason == "ssh_timeout" { Some(3000) } else { None },
+        evidence~,
         duration_ms=(@env.now() - started).to_double(),
         tunnel_directory=directory,
-        recording=workspace_recording(state),
+        environment~,
+        protected_secrets=pairing_secrets,
+        recording=state_recording(state),
       )
     Unsupported =>
       save_diagnostic(
         "relay-probe",
         "unsupported",
         error_type="readiness_unsupported",
+        phase~,
+        exit_code?,
+        evidence~,
         tunnel_directory=directory,
-        recording=workspace_recording(state),
+        environment~,
+        protected_secrets=pairing_secrets,
+        recording=state_recording(state),
       )
   }
   result
"}}

