197	///|
198	priv struct CodexAuth {
199	  access : String
200	  account : String
201	  expiry : Double
202	  secrets : Array[String]
203	}
204	
205	///|
206	async fn read_codex_auth(home : String) -> CodexAuth {
207	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
208	    raise AdapterError("Invalid Codex auth size")
209	  }
210	  let source = @fs.read_file(home + "/auth.json")
211	  guard source.binary().length() <= 65536 else {
212	    raise AdapterError("Invalid Codex auth size")
213	  }
214	  let auth = @json.parse(source.text())
215	  guard (
216	      field(auth, "OPENAI_API_KEY") == None ||
217	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
218	    ) &&
219	    (
220	      field(auth, "auth_mode") == None ||
221	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
222	    ) else {
223	    raise AdapterError("Unsupported Codex auth mode")
224	  }
225	  guard field(auth, "tokens") is Some(tokens) else {
226	    raise AdapterError("Missing Codex auth tokens")
227	  }
228	  let access = required(tokens, "access_token")
229	  let secrets = [access]
230	  for name in ["id_token", "refresh_token"] {
231	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
232	      secrets.push(value)
233	    }
234	  }
235	  let segments = access.split(".").to_array()
236	  guard segments.length() == 3 else {
237	    raise AdapterError("Invalid access token")
238	  }
239	  let encoded = segments[1]
240	    .to_owned()
241	    .replace_all(old="-", new="+")
242	    .replace_all(old="_", new="/")
243	  let padding = (4 - encoded.length() % 4) % 4
244	  let claims = @json.parse(
245	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
246	  )
247	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
248	    raise AdapterError("Invalid access token expiry")
249	  }
250	  { access, account: required(tokens, "account_id"), expiry, secrets, }
251	}
252	
253	///|
254	async fn codex_rpc_response(
255	  reader : @process.ReadFromProcess,
256	  id : Int32,
257	  secrets : Array[String],
258	) -> Unit {
259	  let bytes : Array[Byte] = []
260	  let mut total = 0
261	  while true {
262	    let byte = reader.read_exactly(1)[0]
263	    total += 1
264	    guard total <= 1048576 else {
265	      raise AdapterError("Codex refresh output limit")
266	    }
267	    if byte == b'\n' {
268	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
269	      bytes.clear()
270	      if field(response, "id") == Some(Json::number(id.to_double())) {
271	        if field(response, "error") is Some(error) {
272	          let code = match field(error, "code") {
273	            Some(Json::Number(value, ..)) => " code " + value.to_string()
274	            _ => ""
275	          }
276	          let message = match field(error, "message") {
277	            Some(Json::String(value)) =>
278	              ": " + diagnostic_text(value, protected_secrets=secrets)
279	            _ => ""
280	          }
281	          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
282	        }
283	        guard field(response, "result") != None else {
284	          raise AdapterError("Codex refresh RPC \{id} returned no result")
285	        }
286	        return
287	      }
288	    } else {
289	      bytes.push(byte)
290	    }
291	  }
292	}
293	
294	///|
295	async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
296	  let (reader, output) = @process.read_from_process()
297	  defer reader.close()
298	  let (input, writer) = @process.write_to_process()
299	  defer writer.close()
300	  let (errors, stderr) = @process.read_from_process()
301	  defer errors.close()
302	  let captured = @buffer.Buffer(size_hint=1024)
303	  let incomplete : Ref[Bool] = { val: false, }
304	  let finished : Ref[Bool] = { val: false, }
305	  let failure = try {
306	    @async.with_task_group(async fn(group) {
307	      ignore(
308	        @process.spawn(
309	          group,
310	          "codex",
311	          ["app-server", "--stdio"],
312	          extra_env={ "CODEX_HOME": home },
313	          stdin=input,
314	          stdout=output,
315	          stderr~,
316	          no_wait=true,
317	        ),
318	      )
319	      group.spawn_bg(no_wait=true, async fn() {
320	        while errors.read_some(max_len=4096) is Some(chunk) {
321	          let remaining = 8192 - captured.length()
322	          let count = if chunk.length() < remaining {
323	            chunk.length()
324	          } else {
325	            remaining
326	          }
327	          if count > 0 {
328	            captured.write_bytes(chunk[:count])
329	          }
330	          if count < chunk.length() {
331	            incomplete.val = true
332	          }
333	        }
334	        finished.val = true
335	      })
336	      let initialize : Json = {
337	        "id": 1,
338	        "method": "initialize",
339	        "params": {
340	          "clientInfo": { "name": "orca-env-devsy", "version": version },
341	        },
342	      }
343	      writer.write(initialize.stringify() + "\n")
344	      codex_rpc_response(reader, 1, secrets)
345	      writer.write("{\"method\":\"initialized\"}\n")
346	      writer.write(
347	        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
348	      )
349	      codex_rpc_response(reader, 2, secrets)
350	    })
351	    None
352	  } catch {
353	    error => Some(error)
354	  }
355	  if failure is Some(error) {
356	    if @async.is_being_cancelled() {
357	      raise error
358	    }
359	    let protected_input : Json = { "access_token": secrets }
360	    let detail = diagnostic_output(
361	      captured.to_bytes(),
362	      @env.get_env_vars(),
363	      protected_input=protected_input.stringify(),
364	      omitted=incomplete.val || !finished.val,
365	    )
366	    raise AdapterError(
367	      diagnostic_error(error) +
368	      detail
369	      .map(value => "\nCodex app-server stderr: " + value)
370	      .unwrap_or(
371	        if finished.val {
372	          ""
373	        } else {
374	          "\n[Codex app-server stderr incomplete]"
375	        },
376	      ),
377	    )
378	  }
379	}
380	
381	///|
382	async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
383	  let initial = read_codex_auth(home)
384	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
385	    return initial
386	  }
387	  let lock = @fs.open(
388	    home + "/.orca-env-devsy-refresh.lock",
389	    mode=ReadWrite,
390	    create_mode=OpenOrCreate,
391	    permission=0o600,
392	  )
393	  defer lock.close()
394	  while !lock.try_lock(Exclusive) {
395	    @async.sleep(100)
396	  }
397	  let before = read_codex_auth(home)
398	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
399	    return before
400	  }
401	  let mut phase = "refresh"
402	  try {
403	    refresh_codex(home, before.secrets)
404	    phase = "verify"
405	    let after = read_codex_auth(home)
406	    guard after.access != before.access && after.expiry > before.expiry else {
407	      raise AdapterError("Codex refresh not persisted")
408	    }
409	    save_diagnostic("codex-refresh", "success", recording~)
410	  } catch {
411	    error => {
412	      progress_write(
413	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
414	      )
415	      let detail = diagnostic_error(error)
416	      save_diagnostic(
417	        "codex-refresh",
418	        "warning",
419	        phase~,
420	        error_type=if error is @async.TimeoutError {
421	          "timeout"
422	        } else {
423	          "refresh_failed"
424	        },
425	        error_message=detail,
426	        recording~,
427	      )
428	    }
429	  }
430	  let current = read_codex_auth(home)
431	  guard current.expiry > @env.now().to_double() / 1000 else {
432	    raise AdapterError("Expired access token")
433	  }
434	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
435	    progress_write(
436	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
437	    )
438	  }
439	  current
440	}

