1602	        Workspace => valid_workspace_id(text)
1603	        Identity => text.length() <= 128 && valid_context(text)
1604	        RefName => diagnostic_ref(text)
1605	      }
1606	      let credential_form = text
1607	        .split("/")
1608	        .iter()
1609	        .any(part => {
