1626	///|
1627	// A recording grammar, never a replacement for checkout validation. Excludes
1628	// URLs, credential forms, control characters and Git's invalid ref syntax.
1629	fn diagnostic_ref(text : String) -> Bool {
1630	  text.length() <= 1024 &&
1631	  !text.has_prefix("-") &&
1632	  !text.contains("..") &&
1633	  text
1634	  .split("/")
1635	  .iter()
1636	  .all(part => {
1637	    part != "" &&
1638	    !part.has_prefix(".") &&
1639	    !part.has_suffix(".") &&
1640	    !part.has_suffix(".lock")
1641	  }) &&
1642	  text
1643	  .iter()
1644	  .all(c => {
1645	    (c >= 'a' && c <= 'z') ||
1646	    (c >= 'A' && c <= 'Z') ||
1647	    (c >= '0' && c <= '9') ||
1648	    c == '/' ||
1649	    c == '-' ||
1650	    c == '_' ||
1651	    c == '.'
1652	  })
1653	}
