  1757	// Inspect only the strategy flags in the actual invocation. Other arguments
  1758	// never enter the diagnostic record. Devsy uses the last valid repeated flag.
  1759	fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
  1760	  let mut strategy = "full"
  1761	  let mut count = 0
  1762	  let mut invalid = false
  1763	  let mut index = 0
  1764	  while index < args.length() {
  1765	    let argument = args[index]
  1766	    let value = if argument == "--git-clone-strategy" {
  1767	      count += 1
  1768	      index += 1
  1769	      if index < args.length() {
  1770	        Some(args[index])
  1771	      } else {
  1772	        None
  1773	      }
  1774	    } else if argument.has_prefix("--git-clone-strategy=") {
  1775	      count += 1
  1776	      Some(argument[21:].to_owned())
  1777	    } else {
  1778	      None
  1779	    }
  1780	    if count > 0 &&
  1781	      (
  1782	        argument == "--git-clone-strategy" ||
  1783	        argument.has_prefix("--git-clone-strategy=")
  1784	      ) {
  1785	      match value {
  1786	        Some("") => strategy = "full"
  1787	        Some("shallow" | "blobless" | "treeless" | "bare" as known) =>
  1788	          strategy = known
  1789	        _ => invalid = true
  1790	      }
  1791	    }
  1792	    index += 1
  1793	  }
  1794	  (
  1795	    if invalid {
  1796	      "invalid"
  1797	    } else {
  1798	      strategy
  1799	    },
  1800	    if count > 1 {
  1801	      "upArgs"
  1802	    } else {
  1803	      "adapter"
  1804	    },
  1805	  )
  1806	}
