528	    return
529	  } else if event == Json::null() &&
530	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
531	    self.details_truncated = true
532	    self.message(line, debug=false, warning=true, emit=false)
533	    return
534	  }
535	  self.line(line, statuses~, messages~)
